CREATE TYPE public.centre_role AS ENUM ('md','deputy_md','speech_therapist','occupational_therapist','administrator','assistant','client','caregiver');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated; GRANT UPDATE(display_name,phone) ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.centre_role NOT NULL, UNIQUE(user_id));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_centre_role(roles public.centre_role[]) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role=ANY(roles)) $$;
REVOKE ALL ON FUNCTION public.has_centre_role(public.centre_role[]) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_centre_role(public.centre_role[]) TO authenticated;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_centre_role(ARRAY['md','deputy_md','administrator']::public.centre_role[]));
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_centre_role(ARRAY['md','deputy_md','administrator']::public.centre_role[]));
CREATE FUNCTION public.create_centre_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,COALESCE(NEW.raw_user_meta_data->>'display_name',NEW.raw_user_meta_data->>'full_name','')); RETURN NEW; END $$;
CREATE TRIGGER centre_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_centre_profile();
INSERT INTO public.profiles(id,display_name) SELECT id,COALESCE(raw_user_meta_data->>'display_name','') FROM auth.users ON CONFLICT DO NOTHING;
CREATE TABLE public.clients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), full_name text NOT NULL, date_of_birth date, service text NOT NULL DEFAULT 'Speech therapy', status text NOT NULL DEFAULT 'Active' CHECK(status IN ('Active','Discharged','Waitlist')), is_sample boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.clients TO authenticated; GRANT ALL ON public.clients TO service_role;
ALTER TABLE public.clients ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.client_access (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES public.clients(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, UNIQUE(client_id,user_id));
GRANT SELECT,INSERT,DELETE ON public.client_access TO authenticated; GRANT ALL ON public.client_access TO service_role;
ALTER TABLE public.client_access ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.can_access_client(target uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_centre_role(ARRAY['md','deputy_md','administrator']::public.centre_role[]) OR (public.has_centre_role(ARRAY['speech_therapist','occupational_therapist','assistant','client','caregiver']::public.centre_role[]) AND EXISTS(SELECT 1 FROM public.client_access WHERE client_id=target AND user_id=auth.uid())) $$;
REVOKE ALL ON FUNCTION public.can_access_client(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_access_client(uuid) TO authenticated;
CREATE POLICY clients_read ON public.clients FOR SELECT TO authenticated USING(public.can_access_client(id));
CREATE POLICY clients_insert ON public.clients FOR INSERT TO authenticated WITH CHECK(public.has_centre_role(ARRAY['md','deputy_md','administrator']::public.centre_role[]));
CREATE POLICY clients_update ON public.clients FOR UPDATE TO authenticated USING(public.has_centre_role(ARRAY['md','deputy_md','administrator']::public.centre_role[])) WITH CHECK(public.has_centre_role(ARRAY['md','deputy_md','administrator']::public.centre_role[]));
CREATE POLICY access_read ON public.client_access FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_centre_role(ARRAY['md','deputy_md','administrator']::public.centre_role[]));
CREATE POLICY access_insert ON public.client_access FOR INSERT TO authenticated WITH CHECK(public.has_centre_role(ARRAY['md','deputy_md','administrator']::public.centre_role[]));
CREATE POLICY access_delete ON public.client_access FOR DELETE TO authenticated USING(public.has_centre_role(ARRAY['md','deputy_md','administrator']::public.centre_role[]));
CREATE TABLE public.appointments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES public.clients(id), therapist_id uuid REFERENCES public.profiles(id), starts_at timestamptz NOT NULL, duration_minutes integer NOT NULL DEFAULT 45 CHECK(duration_minutes BETWEEN 15 AND 180), service text NOT NULL DEFAULT 'Speech therapy', status text NOT NULL DEFAULT 'Scheduled' CHECK(status IN ('Scheduled','Completed','Cancelled')), is_sample boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE ON public.appointments TO authenticated; GRANT ALL ON public.appointments TO service_role;
ALTER TABLE public.appointments ENABLE ROW LEVEL SECURITY;
CREATE POLICY appointments_read ON public.appointments FOR SELECT TO authenticated USING(public.can_access_client(client_id));
CREATE POLICY appointments_insert ON public.appointments FOR INSERT TO authenticated WITH CHECK(public.has_centre_role(ARRAY['md','deputy_md','administrator']::public.centre_role[]));
CREATE POLICY appointments_update ON public.appointments FOR UPDATE TO authenticated USING(public.has_centre_role(ARRAY['md','deputy_md','administrator']::public.centre_role[]) OR (therapist_id=auth.uid() AND public.can_access_client(client_id) AND public.has_centre_role(ARRAY['speech_therapist','occupational_therapist']::public.centre_role[]))) WITH CHECK(public.has_centre_role(ARRAY['md','deputy_md','administrator']::public.centre_role[]) OR (therapist_id=auth.uid() AND public.can_access_client(client_id) AND public.has_centre_role(ARRAY['speech_therapist','occupational_therapist']::public.centre_role[])));
CREATE TABLE public.clinical_notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES public.clients(id), author_id uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), title text NOT NULL, body text NOT NULL, shared_with_family boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.clinical_notes TO authenticated; GRANT ALL ON public.clinical_notes TO service_role;
ALTER TABLE public.clinical_notes ENABLE ROW LEVEL SECURITY;
CREATE POLICY notes_read ON public.clinical_notes FOR SELECT TO authenticated USING(public.has_centre_role(ARRAY['md','deputy_md']::public.centre_role[]) OR (public.can_access_client(client_id) AND (public.has_centre_role(ARRAY['speech_therapist','occupational_therapist']::public.centre_role[]) OR (public.has_centre_role(ARRAY['assistant']::public.centre_role[]) AND author_id=auth.uid()) OR (public.has_centre_role(ARRAY['client','caregiver']::public.centre_role[]) AND shared_with_family))));
CREATE POLICY notes_insert ON public.clinical_notes FOR INSERT TO authenticated WITH CHECK(author_id=auth.uid() AND public.can_access_client(client_id) AND public.has_centre_role(ARRAY['md','deputy_md','speech_therapist','occupational_therapist','assistant']::public.centre_role[]) AND (NOT shared_with_family OR NOT public.has_centre_role(ARRAY['assistant']::public.centre_role[])));
CREATE POLICY notes_update ON public.clinical_notes FOR UPDATE TO authenticated USING(author_id=auth.uid() AND public.can_access_client(client_id) AND public.has_centre_role(ARRAY['md','deputy_md','speech_therapist','occupational_therapist','assistant']::public.centre_role[])) WITH CHECK(author_id=auth.uid() AND public.can_access_client(client_id) AND public.has_centre_role(ARRAY['md','deputy_md','speech_therapist','occupational_therapist','assistant']::public.centre_role[]) AND (NOT shared_with_family OR NOT public.has_centre_role(ARRAY['assistant']::public.centre_role[])));
CREATE TABLE public.centre_settings (id integer PRIMARY KEY DEFAULT 1 CHECK(id=1), centre_name text NOT NULL DEFAULT 'Wellspring Speech Therapy and Rehabilitation Centre', address text NOT NULL DEFAULT 'Danyame, Kumasi, Ghana', phone text NOT NULL DEFAULT '+233 50 075 8665', timezone text NOT NULL DEFAULT 'Africa/Accra');
GRANT SELECT,UPDATE ON public.centre_settings TO authenticated; GRANT ALL ON public.centre_settings TO service_role;
ALTER TABLE public.centre_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY settings_read ON public.centre_settings FOR SELECT TO authenticated USING(public.has_centre_role(ARRAY['md','deputy_md','administrator','speech_therapist','occupational_therapist','assistant','client','caregiver']::public.centre_role[]));
CREATE POLICY settings_update ON public.centre_settings FOR UPDATE TO authenticated USING(public.has_centre_role(ARRAY['md']::public.centre_role[])) WITH CHECK(public.has_centre_role(ARRAY['md']::public.centre_role[]));
CREATE TABLE public.audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, action text NOT NULL, entity text NOT NULL, record_id text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role;
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_read ON public.audit_logs FOR SELECT TO authenticated USING(public.has_centre_role(ARRAY['md','deputy_md']::public.centre_role[]));
CREATE FUNCTION public.audit_centre_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_logs(actor_id,action,entity,record_id) VALUES(auth.uid(),TG_OP,TG_TABLE_NAME,CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD)->>'id' ELSE to_jsonb(NEW)->>'id' END); RETURN COALESCE(NEW,OLD); END $$;
CREATE TRIGGER audit_clients AFTER INSERT OR UPDATE OR DELETE ON public.clients FOR EACH ROW EXECUTE FUNCTION public.audit_centre_change();
CREATE TRIGGER audit_appointments AFTER INSERT OR UPDATE OR DELETE ON public.appointments FOR EACH ROW EXECUTE FUNCTION public.audit_centre_change();
CREATE TRIGGER audit_notes AFTER INSERT OR UPDATE OR DELETE ON public.clinical_notes FOR EACH ROW EXECUTE FUNCTION public.audit_centre_change();
CREATE TRIGGER audit_roles AFTER INSERT OR UPDATE OR DELETE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.audit_centre_change();
CREATE TRIGGER audit_access AFTER INSERT OR DELETE ON public.client_access FOR EACH ROW EXECUTE FUNCTION public.audit_centre_change();
CREATE TRIGGER audit_settings AFTER UPDATE ON public.centre_settings FOR EACH ROW EXECUTE FUNCTION public.audit_centre_change();
CREATE FUNCTION public.assign_centre_role(target_user uuid,new_role public.centre_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_centre_role(ARRAY['md']::public.centre_role[]) THEN RAISE EXCEPTION 'Only the Managing Director may assign roles'; END IF; IF target_user=auth.uid() THEN RAISE EXCEPTION 'You cannot change your own role'; END IF; INSERT INTO public.user_roles(user_id,role) VALUES(target_user,new_role) ON CONFLICT(user_id) DO UPDATE SET role=EXCLUDED.role; END $$;
REVOKE ALL ON FUNCTION public.assign_centre_role(uuid,public.centre_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.assign_centre_role(uuid,public.centre_role) TO authenticated;
CREATE INDEX client_access_user_idx ON public.client_access(user_id,client_id);
CREATE INDEX appointments_starts_idx ON public.appointments(starts_at);
CREATE INDEX notes_client_idx ON public.clinical_notes(client_id);
CREATE INDEX audit_time_idx ON public.audit_logs(created_at DESC);